package edu.pe.cibertec.saibm.membresia.rest;
import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*; import java.time.*; import java.util.*; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.test.autoconfigure.web.servlet.*; import org.springframework.boot.test.mock.mockito.*; import org.springframework.context.annotation.Import; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import edu.pe.cibertec.saibm.membresia.application.port.in.*; import edu.pe.cibertec.saibm.membresia.infrastructure.in.rest.*;
@WebMvcTest(MembershipController.class) @Import(MembershipExceptionHandler.class) class MembershipRestTest { @Autowired MockMvc mvc; @MockBean MembershipUseCase use; @MockBean TransitionalWriteAuthorizer auth; @Test void planReadExposesConfiguredLimit(){when(use.activePlans(any())).thenReturn(List.of(new MembershipUseCase.PlanView(UUID.randomUUID(),"gold","Gold",17,2,Instant.parse("2030-01-01T00:00:00Z"),null,true)));try{mvc.perform(get("/api/v1/memberships/plans")).andExpect(status().isOk()).andExpect(jsonPath("$[0].reservationLimit").value(17));}catch(Exception e){throw new RuntimeException(e);}} @Test void assignmentWriteFailsClosedWithoutTransitionalSignature() throws Exception {doThrow(new WriteAuthorizationException()).when(auth).require(any());mvc.perform(post("/api/v1/memberships/assignments").header("Idempotency-Key","k").contentType(MediaType.APPLICATION_JSON).content("{\"userId\":\"u-1\",\"planId\":\"00000000-0000-0000-0000-000000000001\"}")).andExpect(status().isForbidden()).andExpect(jsonPath("$.status").value(403));} @Test void adminPlanUpdateIsProtectedAndVersioned() throws Exception {var id=UUID.randomUUID();var view=new MembershipUseCase.PlanView(id,"gold","Gold v2",21,3,Instant.parse("2030-01-01T00:00:00Z"),null,true);doThrow(new WriteAuthorizationException()).when(auth).require(any());mvc.perform(put("/api/v1/memberships/plans/"+id).contentType(MediaType.APPLICATION_JSON).content("{\"code\":\"gold\",\"name\":\"Gold v2\",\"reservationLimit\":21,\"validFrom\":\"2030-01-01T00:00:00Z\"}")).andExpect(status().isForbidden());reset(auth);when(use.updatePlan(eq(id),any())).thenReturn(view);mvc.perform(put("/api/v1/memberships/plans/"+id).header("X-SAIBM-Write-Timestamp","1").contentType(MediaType.APPLICATION_JSON).content("{\"code\":\"gold\",\"name\":\"Gold v2\",\"reservationLimit\":21,\"validFrom\":\"2030-01-01T00:00:00Z\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.version").value(3));}}
